import {INITIAL_SKILLS,DEFAULT_TRAINING,DEFAULT_ABSENCE,SCENARIOS,workloadFor,simulate} from './engine.js?v=0.16.0';
const clone=x=>structuredClone(x);
export const KEY='thinking-lab:knowledge:v1';
export const initial=()=>({version:2,skills:clone(INITIAL_SKILLS),sessions:[{...DEFAULT_TRAINING,id:'first'}],selected:'first',focus:[-1,-1,-1,-1],absences:[{...DEFAULT_ABSENCE,to:24,id:'away'}],scenario:'battery',workload:workloadFor(),week:12,baseline:null,decision:''});
function num(v,min,max,integer=false){if(!Number.isFinite(v)||v<min||v>max||integer&&!Number.isInteger(v))throw Error('A number is outside the supported range.');}
function id(v){if(typeof v!=='string'||!v.length||v.length>100)throw Error('Invalid identifier.');}
function array(a,n,fn){if(!Array.isArray(a)||a.length>n)throw Error('Invalid collection.');a.forEach(fn);}
function upgradePlan(p){if(!p.sessions)p.sessions=[{...p.training,id:'first'}];return p;}
function plan(p){upgradePlan(p);if(!Array.isArray(p.skills)||p.skills.length!==4||!Array.isArray(p.focus)||p.focus.length!==4)throw Error('Four people are required.');p.skills.forEach(row=>{if(!Array.isArray(row)||row.length!==3)throw Error('Three skills are required.');row.forEach(v=>num(v,0,1));});p.focus.forEach(v=>num(v,-1,2,true));array(p.sessions,6,x=>{id(x.id);if(typeof x.enabled!=='boolean')throw Error('Invalid coaching state.');num(x.mentor,0,3,true);num(x.learner,0,3,true);num(x.skill,0,2,true);num(x.duration,2,10,true);num(x.start,1,25-x.duration,true);num(x.fraction,.1,.6);});if(new Set(p.sessions.map(x=>x.id)).size!==p.sessions.length)throw Error('Duplicate coaching identifier.');return p;}
export function validate(raw){const s=clone(raw);if(!s||typeof s!=='object')throw Error('Choose a Knowledge experiment.');plan(s);if(!SCENARIOS[s.scenario])throw Error('Unknown workload.');s.workload??=workloadFor(s.scenario);for(const key of ['before','after']){if(!Array.isArray(s.workload[key])||s.workload[key].length!==3)throw Error('Three demand values are required.');s.workload[key].forEach(v=>num(v,0,4));}num(s.workload.changeWeek,1,25,true);
 if(!s.absences)s.absences=s.absence?.person>=0&&s.absence.from<=24?[{...s.absence,to:24,id:'away'}]:[];
 array(s.absences,8,a=>{id(a.id);num(a.person,0,3,true);num(a.from,1,24,true);num(a.to,a.from,24,true);});if(new Set(s.absences.map(a=>a.id)).size!==s.absences.length)throw Error('Duplicate absence identifier.');num(s.week,1,24,true);if(s.baseline)plan(s.baseline);s.selected=s.sessions.some(p=>p.id===s.selected)?s.selected:s.sessions[0]?.id||null;s.decision??='';if(typeof s.decision!=='string'||s.decision.length>20000)throw Error('Decision note is too long.');s.version=2;return s;}
export function pin(s){return clone({skills:s.skills,sessions:s.sessions,focus:s.focus});}
export function replay(s){return {current:simulate(s),baseline:s.baseline?simulate({...s,skills:s.baseline.skills,sessions:s.baseline.sessions,focus:s.baseline.focus}):null};}
export function template(name){const base={...DEFAULT_TRAINING};if(name==='none')return [];if(name==='spread')return [{...base,id:'a',duration:3},{...base,id:'b',learner:0,start:5,duration:3}];if(name==='relay')return [{...base,id:'a',duration:3},{...base,id:'b',mentor:3,learner:0,start:5,duration:3}];return [{...base,id:'first'}];}
export function portable(s){return JSON.stringify({kind:'knowledge',version:2,state:validate(s)},null,2);}
export function parse(raw){const data=JSON.parse(raw);if(data.kind!=='knowledge'||![1,2].includes(data.version))throw Error('Choose an exported Knowledge experiment.');return validate(data.state);}
export function markdown(s){const {current:r,baseline:b}=replay(s);return `# Who else can do the work?\n\n${SCENARIOS[s.scenario].name}. After 24 weeks: ${r.final.delivered.toFixed(1)} completed; ${r.final.totalBacklog.toFixed(1)} waiting; ${r.final.learningTime.toFixed(1)} person-weeks of coaching.\n\n${b?`Pinned plan on the same demand and absences: ${b.final.delivered.toFixed(1)} completed; ${b.final.totalBacklog.toFixed(1)} waiting. Starting knowledge ${JSON.stringify(s.skills)===JSON.stringify(s.baseline.skills)?'matches':'differs; this is not a coaching-only comparison'}.\n\n`:''}Decision / next question: ${s.decision||'Not recorded.'}\n\nFictional divisible work. All coaching requests share finite person-time; gains arrive at week end. The 60% coverage threshold is an assumption, not certification.\n\n\`\`\`json\n${JSON.stringify({experiment:JSON.parse(portable(s)),weekly:r.history,baselineWeekly:b?.history},null,2)}\n\`\`\`\n`;}
